152	        this.householdMemberCount = householdMemberCount;
153	    }
154	
155	    /**
156	     * Builds the derived identity key that consolidates all owner duplicate detection into a
157	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
158	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
159	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
160	     * equal, so a difference in any of the three parts (for example two household mates with
161	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
162	     *
163	     * @param telephone the normalized E.164 telephone
164	     * @param email the lower-cased email, or {@code null} when none
165	     * @param householdId the shared household identifier, or {@code null} when none
166	     * @return the derived identity key
167	     */
168	    public static String identityKey(String telephone, String email, String householdId) {
169	        return (telephone == null ? "" : telephone) + "|"
170	            + (email == null ? "" : email) + "|"
171	            + (householdId == null ? "" : householdId);
172	    }
173	
174	    /**
175	     * Returns this owner's derived identity key, see
176	     * {@link #identityKey(String, String, String)}.
177	     *
178	     * @return the derived identity key for this owner
179	     */
180	    @Transient
181	    public String getIdentityKey() {
182	        return identityKey(this.telephone, this.email, this.householdId);
183	    }
184	
185	    /**
186	     * Fixed city-to-region table: the canonical region each known city belongs to
187	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
188	     * absent from this table has no known region.
189	     */
190	    private static final Map<String, String> CITY_REGIONS = Map.of(
191	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
192	
193	    /**
194	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
195	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
196	     * region string, or {@code null} when the city has no known region. This is the single
197	     * definition of the city-to-region mapping, shared by every rule that derives a region
198	     * from an owner's city.
199	     *
200	     * @param city the city to resolve
201	     * @return the canonical region, or {@code null} when the city has no known region
202	     */
203	    public static String regionForCity(String city) {
204	        return CITY_REGIONS.get(city);
205	    }
206	
207	    /**
208	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
209	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
210	     * A region absent from this table has no fixed range.
211	     */
212	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
213	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
214	
215	    /**
216	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
217	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
218	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
219	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
220	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
221	     *
222	     * @param region the region to resolve, or {@code null}
223	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
224	     */
225	    public static int[] postcodeRangeForRegion(String region) {
226	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
227	    }
228	
229	    /**
230	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
231	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
232	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
233	     * value, or falls in no known range. This is the single definition of the postcode-to-region
234	     * mapping, shared by every rule that derives a region from a postcode.
235	     *
236	     * @param postcode the postcode to resolve
237	     * @return the canonical region, or {@code null} when the postcode maps to no known region
238	     */
239	    public static String regionForPostcode(String postcode) {
240	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
241	            return null;
242	        }
243	        int value = Integer.parseInt(postcode);
244	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
245	            int[] range = entry.getValue();
246	            if (value >= range[0] && value <= range[1]) {
247	                return entry.getKey();
248	            }
249	        }
250	        return null;
251	    }
252	
253	    /**
254	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
255	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
256	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
257	     * range does derivation fall back to the fixed city-to-region table (see
258	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
259	     * resolves to a known region. This is the single definition of an owner's region, shared by
260	     * every rule that derives a region from an owner.
261	     *
262	     * @return the owner's canonical region, or {@code null} when it has no known region
263	     */
264	    @Transient
265	    public String getRegion() {
266	        String region = regionForPostcode(this.postcode);
267	        return region != null ? region : regionForCity(this.city);
268	    }
269	
270	    /**
271	     * Returns this owner's numeric membership level, assigned on creation. The level starts at
272	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
273	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
274	     *
275	     * @return the owner's membership level
276	     */
277	    @Transient
278	    public Integer getMembershipLevel() {
279	        int level = 1;
280	        boolean hasEmail = this.email != null && !this.email.isBlank();
281	        if (hasEmail) {
282	            level++;
283	        }
284	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
285	        if (noNamesakes) {
286	            level++;
287	        }
288	        return Math.min(level, 3);
289	    }
290	
291	    /**
292	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
293	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
294	     * {@code null} when the owner has no customer code or registration date.
295	     *
296	     * @return the owner's membership number, or {@code null} when it cannot be derived
297	     */
298	    @Transient
299	    public String getMembershipNumber() {
300	        if (this.customerCode == null || this.registrationDate == null) {
301	            return null;
302	        }
303	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
304	    }
305	
306	    /**
307	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
308	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
309	     *
310	     * @return the owner's check digit, or {@code null} when it has no customer code
311	     */
312	    @Transient
313	    public Integer getCheckDigit() {
314	        if (this.customerCode == null) {
315	            return null;
316	        }
317	        String code = this.customerCode;
318	        int sum = 0;
319	        boolean dbl = true;
320	        for (int i = code.length() - 1; i >= 0; i--) {
321	            char c = code.charAt(i);
322	            if (c < '0' || c > '9') {
323	                continue;
324	            }
325	            int d = c - '0';
326	            if (dbl) {
327	                d *= 2;
328	                if (d > 9) {
329	                    d -= 9;
330	                }
331	            }
332	            sum += d;
333	            dbl = !dbl;
334	        }
335	        return (10 - (sum % 10)) % 10;
336	    }
337	
338	    protected Set<Pet> getPetsInternal() {
339	        if (this.pets == null) {
340	            this.pets = new HashSet<>();
341	        }
342	        return this.pets;
343	    }
344	
345	    protected void setPetsInternal(Set<Pet> pets) {
346	        this.pets = pets;
347	    }
348	
349	    public List<Pet> getPets() {
350	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
351	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
352	        return Collections.unmodifiableList(sortedPets);
353	    }
354	
355	    public void setPets(List<Pet> pets) {
356	        this.pets = new HashSet<>(pets);
357	    }
358	
359	    public void addPet(Pet pet) {
360	        getPetsInternal().add(pet);
361	        pet.setOwner(this);
362	    }
363	
364	    /**
365	     * Return the Pet with the given name, or null if none found for this Owner.
366	     *
367	     * @param name to test
368	     * @return true if pet name is already in use
369	     */
370	    public Pet getPet(String name) {
371	        return getPet(name, false);
372	    }
373	
374	    /**
375	     * Return the Pet with the given name, or null if none found for this Owner.
376	     *
377	     * @param name to test
378	     * @return true if pet name is already in use
379	     */
380	    public Pet getPet(String name, boolean ignoreNew) {
381	        name = name.toLowerCase();
382	        for (Pet pet : getPetsInternal()) {
383	            if (!ignoreNew || !pet.isNew()) {
384	                String compName = pet.getName();
385	                compName = compName.toLowerCase();
386	                if (compName.equals(name)) {
387	                    return pet;
388	                }
389	            }
390	        }
391	        return null;
392	    }
393	
394	    public Pet getPet(Integer petId) {
395	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
396	    }
397	
398	    @Override
399	    public String toString() {
400	        return new ToStringCreator(this)
401	
402	            .append("id", this.getId())
403	            .append("new", this.isNew())
404	            .append("lastName", this.getLastName())
405	            .append("firstName", this.getFirstName())
406	            .append("address", this.address)
407	            .append("city", this.city)
408	            .append("telephone", this.telephone)
409	            .append("email", this.email)
410	            .toString();
411	    }
412	}
