253	    /**
254	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
255	     * falls on a business day. The date supplied on the request is used when present, otherwise the
256	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
257	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
258	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
259	     * membership number's year segment, the per-day create limit) is computed against.
260	     *
261	     * A supplied registration date later than the server's current date is rejected with an
262	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
263	     *
264	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
265	     * @return the effective registration date rolled forward to the next business day
266	     */
267	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
268	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
269	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
270	            throw new InvalidFieldsException(List.of("registrationDate"));
271	        }
272	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
273	        return toBusinessDay(effective);
274	    }
275	
276	    /**
277	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
278	     * following Monday, while a weekday is returned unchanged.
279	     *
280	     * @param date the date to adjust
281	     * @return the same date when it is a weekday, otherwise the next Monday
282	     */
283	    private LocalDate toBusinessDay(LocalDate date) {
284	        java.time.DayOfWeek day = date.getDayOfWeek();
285	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
286	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
287	        }
288	        return date;
289	    }
