291	    /**
292	     * The maximum number of owners that may be created on a single day. Once this many owners
293	     * already carry today's {@code registrationDate}, no further owner may be created today.
294	     */
295	    private static final long DAILY_OWNER_LIMIT = 100L;
296	
297	    /**
298	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
299	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
300	     * date the new owner would be stored with, so owners are capped per business day. When the limit
301	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
302	     * advice renders as a 429 Too Many Requests response.
303	     *
304	     * @param registrationDate the adjusted business-day registration date of the owner being created
305	     */
306	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
307	        long count = this.clinicService.findAllOwners().stream()
308	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
309	            .count();
310	        if (count >= DAILY_OWNER_LIMIT) {
311	            throw new DailyOwnerLimitExceededException(registrationDate);
312	        }
313	    }
