316	     * The number of owners that may carry a single day's {@code registrationDate} before that day
317	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
318	     * the create and read responses report {@code bulkSignupWarning} true for that date.
319	     */
320	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
321	
322	    /**
323	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
324	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
325	     * count is taken against the same adjusted date owners are stored with, mirroring the
326	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
327	     *
328	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
329	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
330	     */
331	    private boolean bulkSignupWarning(LocalDate registrationDate) {
332	        if (registrationDate == null) {
333	            return false;
334	        }
335	        long count = this.clinicService.findAllOwners().stream()
336	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
337	            .count();
338	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
339	    }
