364	    /**
365	     * Builds the customer code assigned to a newly created owner. The code is formatted as
366	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
367	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
368	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
369	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
370	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
371	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
372	     * identity scheme needs.
373	     *
374	     * @param owner the owner being created, whose fields the code is derived from
375	     * @return the formatted customer code
376	     */
377	    private String customerCodeFor(Owner owner) {
378	        String region = owner.getRegion();
379	        String regionCode = region != null ? region : "UNKNOWN";
380	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
381	        return regionCode + "-" + hash8;
382	    }
