401	    /**
402	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
403	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
404	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
405	     * the names of every offending field, which the exception advice renders as a 400 response
406	     * with an {@code errors} array.
407	     *
408	     * @param ownerFieldsDto the submitted owner fields
409	     */
410	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
411	        List<String> missing = new ArrayList<>();
412	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
413	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
414	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
415	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
416	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
417	        if (!missing.isEmpty()) {
418	            throw new RequiredFieldsMissingException(missing);
419	        }
420	    }
