428	    /**
429	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
430	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
431	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
432	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
433	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
434	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
435	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
436	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
437	     *
438	     * @param telephone the submitted telephone value
439	     * @return the normalized E.164 telephone
440	     */
441	    private String normalizeTelephone(String telephone) {
442	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
443	        String e164;
444	        if (cleaned.startsWith("+")) {
445	            e164 = "+" + cleaned.substring(1);
446	        } else {
447	            String national = cleaned;
448	            if (national.startsWith("0")) {
449	                national = national.substring(1);
450	            }
451	            e164 = "+61" + national;
452	        }
453	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
454	            throw new InvalidFieldsException(List.of("telephone"));
455	        }
456	        validateNationalNumberLength(e164);
457	        return e164;
458	    }
459	
460	    /**
461	     * The required national-number length (the digits after the country code) for each country
462	     * code we recognize: {@code '+61'} (Australia) requires 9 national digits and {@code '+1'}
463	     * (NANP) requires 10. Keyed by the country-code digits without the leading {@code '+'}.
464	     */
465	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
466	        java.util.Map.of("61", 9, "1", 10);
467	
468	    /**
469	     * Validates the national-number length of an already syntactically valid E.164 telephone
470	     * against its country code. For each recognized country code the digits following the code
471	     * must have exactly the expected length ({@code '+61'} => 9 national digits, {@code '+1'} =>
472	     * 10). When the country code is recognized but the national number is the wrong length an
473	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
474	     * response naming the {@code telephone} field. A country code that is not recognized carries
475	     * no per-country length rule and is left to the general 8-to-15-digit E.164 check.
476	     *
477	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
478	     */
479	    private void validateNationalNumberLength(String e164) {
480	        String digits = e164.substring(1);
481	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
482	            .filter(entry -> digits.startsWith(entry.getKey()))
483	            // longest matching country code wins, so a shorter code cannot shadow a longer one
484	            .max(java.util.Comparator.comparingInt(entry -> entry.getKey().length()))
485	            .ifPresent(entry -> {
486	                int nationalLength = digits.length() - entry.getKey().length();
487	                if (nationalLength != entry.getValue()) {
488	                    throw new InvalidFieldsException(List.of("telephone"));
489	                }
490	            });
491	    }
492	
493	    /**
494	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
495	     * and a domain containing at least one dot, none of the parts holding whitespace or a
496	     * second {@code @}.
497	     */
498	    private static final java.util.regex.Pattern EMAIL_PATTERN =
499	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
500	
501	    /**
502	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
503	     * accepted and returned unchanged. When present it must be a syntactically valid address;
504	     * the value is stored and returned lower-cased. When present but invalid an
505	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
506	     * response naming the {@code email} field.
507	     *
508	     * @param email the submitted email value, or {@code null} when omitted
509	     * @return the lower-cased email, or {@code null} when none was supplied
510	     */
511	    private String normalizeEmail(String email) {
512	        if (email == null) {
513	            return null;
514	        }
515	        String trimmed = email.trim();
516	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
517	            throw new InvalidFieldsException(List.of("email"));
518	        }
519	        return canonicalEmail(trimmed);
520	    }
521	
522	    /**
523	     * Reduces an email to the canonical form used both to store it and to compare it against
524	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
525	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
526	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
527	     * value read back off an existing owner without risk of rejecting it. This is the single
528	     * definition of email identity: two emails denote the same address exactly when they
529	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
530	     * an email already on an existing owner can be compared for equality after both pass through
531	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
532	     *
533	     * @param email the email to canonicalize, or {@code null} when none was supplied
534	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
535	     */
536	    private String canonicalEmail(String email) {
537	        if (email == null) {
538	            return null;
539	        }
540	        return email.trim().toLowerCase(java.util.Locale.ROOT);
541	    }
542	
543	    /**
544	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
545	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
546	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
547	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
548	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
549	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
550	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
551	     * 400 response naming the {@code postcode} field.
552	     *
553	     * @param postcode the submitted postcode, or {@code null} when omitted
554	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
555	     */
556	    private void validatePostcode(String postcode, String city) {
557	        if (postcode == null) {
558	            return;
559	        }
560	        if (!postcode.matches("^[0-9]{4}$")) {
561	            throw new InvalidFieldsException(List.of("postcode"));
562	        }
563	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
564	        if (range != null) {
565	            int value = Integer.parseInt(postcode);
566	            if (value < range[0] || value > range[1]) {
567	                throw new InvalidFieldsException(List.of("postcode"));
568	            }
569	        }
570	    }
571	
572	    /**
573	     * Rejects a new owner whose derived identity key is already used by any existing owner. All
574	     * duplicate detection is consolidated into this single key (see
575	     * {@link Owner#identityKey(String, String, String)}): the normalized E.164 telephone, the
576	     * canonical (trimmed, lower-cased) email and the household identifier the owner would receive,
577	     * joined by {@code '|'}. The submitted telephone and email have already been normalized in
578	     * place, and the household identifier is the value {@link #assignHousehold} would later store
579	     * (see {@link #prospectiveHouseholdId(OwnerFieldsDto)}). An owner is a duplicate only when its
580	     * whole key equals an existing owner's, so a difference in any part — for example two members
581	     * of one household with different telephones — yields distinct keys and is allowed. When a
582	     * match is found a {@link DuplicateIdentityException} is thrown, which the exception advice
583	     * renders as a 409 Conflict response.
584	     *
585	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
586	     */
587	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
588	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
589	            canonicalEmail(ownerFieldsDto.getEmail()), prospectiveHouseholdId(ownerFieldsDto));
590	        boolean taken = this.clinicService.findAllOwners().stream()
591	            .anyMatch(existing -> identityKey.equals(Owner.identityKey(existing.getTelephone(),
592	                canonicalEmail(existing.getEmail()), existing.getHouseholdId())));
593	        if (taken) {
594	            throw new DuplicateIdentityException(identityKey);
595	        }
596	    }
597	
598	    /**
599	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
600	     * set to {@code true}. The identifier is the one the owner would receive
601	     * ({@link #prospectiveHouseholdId(OwnerFieldsDto)}), derived deterministically from its
602	     * household identity so every owner in the same household resolves to the same stable value.
603	     * The new owner receives that value, and any existing household mates that do not yet carry it
604	     * are updated so the whole household shares one identifier. When the request did not opt in the
605	     * owner is left without a household identifier.
606	     *
607	     * @param owner the newly created owner, mutated in place with its household identifier
608	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
609	     */
610	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
611	        String householdId = prospectiveHouseholdId(ownerFieldsDto);
612	        if (householdId == null) {
613	            return;
614	        }
615	        owner.setHouseholdId(householdId);
616	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
617	            if (!householdId.equals(mate.getHouseholdId())) {
618	                mate.setHouseholdId(householdId);
619	                this.clinicService.saveOwner(mate);
620	            }
621	        }
622	    }
623	
624	    /**
625	     * Derives the {@code householdId} a newly submitted owner would receive, without needing the
626	     * owner to have been mapped or persisted yet. An owner shares a household only when the request
627	     * opts in via {@code sharesHousehold}; when it does, the identifier is derived deterministically
628	     * from the owner's household identity (its {@code lastName} and {@code address}, see
629	     * {@link #householdIdFor(String, String)}), so it matches the value {@link #assignHousehold} will
630	     * later store and every household mate resolves to the same identifier. When the request did not
631	     * opt in the owner belongs to no shared household and {@code null} is returned.
632	     *
633	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
634	     * @return the household identifier the owner would receive, or {@code null} when it shares none
635	     */
636	    private String prospectiveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
637	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
638	            return null;
639	        }
640	        return householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
641	    }
642	
643	    /**
644	     * Derives the stable {@code householdId} shared by every owner in the household identified by
645	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
646	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
647	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
648	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
649	     *
650	     * @param lastName the household's last name
651	     * @param address the household's address
652	     * @return the deterministic household identifier
653	     */
654	    private String householdIdFor(String lastName, String address) {
655	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
656	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
657	        return "HH-" + shaHex(key, 16);
658	    }
659	
660	    /**
661	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
662	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
663	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
664	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
665	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
666	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
667	     * an {@link IllegalStateException} is thrown.
668	     *
669	     * @param input the string to hash
670	     * @param hexChars the number of leading upper-case hex characters to return
671	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
672	     */
673	    private String shaHex(String input, int hexChars) {
674	        try {
675	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
676	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
677	            StringBuilder sb = new StringBuilder();
678	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
679	                sb.append(String.format("%02X", digest[i]));
680	            }
681	            return sb.substring(0, hexChars);
682	        }
683	        catch (java.security.NoSuchAlgorithmException e) {
684	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
685	        }
686	    }
687	
688	    /**
689	     * Counts the owners that belong to the household identified by the given {@code householdId},
690	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
691	     * of owners, so after a create it reflects the household's size including the newly persisted
692	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
693	     * household and yields {@code 0}.
694	     *
695	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
696	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
697	     */
698	    private int countHouseholdMembers(String householdId) {
699	        if (householdId == null) {
700	            return 0;
701	        }
702	        return (int) this.clinicService.findAllOwners().stream()
703	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
704	            .count();
705	    }
706	
707	    /**
708	     * Finds every existing owner that shares a household with the given {@code lastName} and
709	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
710	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
711	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
712	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
713	     * every rule that reasons about households.
714	     *
715	     * @param lastName the last name to match on
716	     * @param address the address to match on
717	     * @return the owners sharing the household, in encounter order (possibly empty)
718	     */
719	    private List<Owner> findHouseholdMates(String lastName, String address) {
720	        String normalizedLastName = collapseWhitespace(lastName);
721	        String normalizedAddress = normalizeAddress(address);
722	        return this.clinicService.findAllOwners().stream()
723	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
724	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
725	            .toList();
726	    }
727	
728	    /**
729	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
730	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
731	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
732	     *
733	     * @param value the value to collapse, or {@code null}
734	     * @return the whitespace-collapsed value, never {@code null}
735	     */
736	    private String collapseWhitespace(String value) {
737	        if (value == null) {
738	            return "";
739	        }
740	        return value.trim().replaceAll("\\s+", " ");
741	    }
742	
743	    /**
744	     * Common street-type abbreviations expanded during address normalization, keyed by their
745	     * upper-cased token.
746	     */
747	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
748	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
749	
750	    /**
751	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
752	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
753	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
754	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
755	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
756	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
757	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
758	     * everywhere an address is stored or compared.
759	     *
760	     * @param address the submitted address value, or {@code null}
761	     * @return the normalized address, never {@code null}
762	     */
763	    private String normalizeAddress(String address) {
764	        if (address == null) {
765	            return "";
766	        }
767	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
768	        if (collapsed.isEmpty()) {
769	            return "";
770	        }
771	        String[] tokens = collapsed.split(" ");
772	        StringBuilder sb = new StringBuilder(collapsed.length());
773	        for (int i = 0; i < tokens.length; i++) {
774	            if (i > 0) {
775	                sb.append(' ');
776	            }
777	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
778	        }
779	        return sb.toString();
780	    }
781	}
